async function fetchBizno(bizno) {
    const clean = bizno.replace(/[^0-9]/g, '');
    const url = 'https://bizno.net/article/' + clean;
    return new Promise(resolve => {
        https.get(url, { headers: { 'User-Agent': 'Mozilla/5.0' } }, res => {
            let d = '';
            res.on('data', c => d += c);
            res.on('end', () => {
                const info = {};
                // 등록일: e.g. 2009-04-20
                const regM = d.match(/<th>등록일<\/th>\s*<td>(.*?)<\/td>/s);
                if (regM) info.regDate = regM[1].replace(/<[^>]+>/g, '').trim();

                // 전화번호
                const telM = d.match(/<th>전화번호<\/th>\s*<td>(.*?)<\/td>/s);
                if (telM) info.tel = telM[1].replace(/<[^>]+>/g, '').trim();

                // 팩스번호
                const faxM = d.match(/<th>팩스번호<\/th>\s*<td>(.*?)<\/td>/s);
                if (faxM) info.fax = faxM[1].replace(/<[^>]+>/g, '').trim();

                // 종업원수
                const empM = d.match(/<th>종업원수<\/th>\s*<td>(.*?)<\/td>/s);
                if (empM) info.employees = empM[1].replace(/<[^>]+>/g, '').trim();

                // 상태
                const stM = d.match(/<th>사업자 현재 상태<\/th>\s*<td>(.*?)<\/td>/s);
                if (stM) info.status = stM[1].replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').trim();

                resolve(info);
            });
        }).on('error', () => resolve({}));
    });
}

async function run() {
    for (let i = 0; i < 5; i++) {
        const item = list[i];
        const info = await fetchBizno(item.bizno);
        console.log(item.rowNumber, item.name, item.bizno, info);
    }
}
run();
