"const https = require('https');
const iconv = require('iconv-lite');

function fetch(url, encoding = 'utf-8') {
  return new Promise((resolve) => {
    https.get(url, (res) => {
      let chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => {
        const buf = Buffer.concat(chunks);
        if (encoding === 'euc-kr') {
          resolve(iconv.decode(buf, 'euc-kr'));
        } else {
          resolve(buf.toString('utf-8'));
        }
      });
    }).on('error', () => resolve(''));
  });
}

async function run() {
  const page = await fetch('https://book.mcst.go.kr/html/searchList.php');
  const m = page.match(/charset=([^\s"'>]+)/i);
  console.log('Page charset:', m ? m[1] : 'not specified');

  // Let's test search with '동아대학교' which we know is there
