  const res1 = await fetch(url1);
  const hasDongA = res1.includes('동아대');
  console.log('UTF-8 "동아대" found?', hasDongA);
  if (hasDongA) {
    const rows = res1.match(/<tr[\s\S]*?<\/tr>/gi) || [];
    rows.slice(1, 4).forEach(r => console.log('Row:', r.replace(/\s+/g, ' ')));
  }

  // If not found, try euc-kr encoding
  const eucBuf = iconv.encode('동아대', 'euc-kr');
  let eucEncoded = '';
  for (const b of eucBuf) {
    eucEncoded += '%' + b.toString(16).toUpperCase();
  }
  const url2 = 'https://book.mcst.go.kr/html/searchList.php?search_area=6260000&search_state=13&search_kind=&search_type=1&search_word=' + eucEncoded;
